package fulguris.adrules

import org.json.JSONArray
import org.json.JSONObject

/**
 * AI community per-site rule, as generated by the NAS analysis pipeline and
 * distributed through the PHP bridge (site-rules.json).
 *
 * Shape follows the five-layer interception design:
 *  - [hosts]        -> Layer 1: per-site additions to the network blocklist (host suffix match)
 *  - [htmlSig]      -> Layer 2: structural signatures for stripping inline ad scripts in the main frame
 *  - [navAllow]     -> Layer 3: navigation gate whitelist (page host must stay within these hosts)
 *  - [rules]        -> Layer 4: behavioural DOM sweeper rules, see AdCleaner.js
 *  - [cosmetic]     -> Layer 4: plain cosmetic selectors, hidden via CSS
 *
 * Rules describe behaviour shapes, never concrete strings, because adversaries
 * rotate domains/classes/ports (see the technical notes).
 */
data class SiteRule(
    val domain: String,
    val version: Int = 1,
    val hosts: List<String> = emptyList(),
    val htmlSig: List<String> = emptyList(),
    val navAllow: List<String> = emptyList(),
    val rules: List<String> = emptyList(),
    val cosmetic: List<String> = emptyList(),
) {

    /**
     * True if this host equals [host] or is a subdomain of it.
     * Strict suffix match, never contains(), so that
     * notexample.com or example.com.evil.net cannot match example.com.
     */
    fun matchesHost(host: String): Boolean {
        val h = host.lowercase()
        val d = domain.lowercase()
        return h == d || h.endsWith(".$d")
    }

    /**
     * Layer 3: is [targetHost] allowed to be navigated to while on this site?
     * An empty [navAllow] means no gate for this site.
     */
    fun isNavAllowed(targetHost: String): Boolean {
        if (navAllow.isEmpty()) return true
        val t = targetHost.lowercase()
        return navAllow.any { allowed ->
            val a = allowed.trim().lowercase()
            when {
                a == "*" -> true
                a.startsWith("*.") -> t == a.substring(2) || t.endsWith(a.substring(1))
                else -> t == a || t.endsWith(".$a")
            }
        }
    }

    companion object {

        /**
         * Parse one site entry from the distributed JSON.
         * Every field is defensive: a malformed entry yields null and is skipped (fail-open).
         */
        fun fromJson(json: JSONObject): SiteRule? {
            val domain = json.optString("domain").trim().lowercase()
            if (domain.isEmpty()) return null
            return SiteRule(
                domain = domain,
                version = json.optInt("v", 1),
                hosts = json.optStringList("hosts"),
                htmlSig = json.optStringList("htmlSig"),
                navAllow = json.optStringList("navAllow"),
                rules = json.optStringList("rules"),
                cosmetic = json.optStringList("cosmetic"),
            )
        }

        private fun JSONObject.optStringList(key: String): List<String> =
            optJSONArray(key)?.let(::toStringList) ?: emptyList()

        private fun toStringList(array: JSONArray): List<String> {
            val list = mutableListOf<String>()
            for (i in 0 until array.length()) {
                val s = array.optString(i)
                if (s.isNotBlank()) list.add(s)
            }
            return list
        }
    }
}

/**
 * Whole rules index: the site-rules.json document.
 */
data class SiteRulesIndex(
    val version: Int,
    val sites: List<SiteRule>,
) {

    /**
     * Most specific rule wins: longest matching domain wins so that
     * a rule for "sub.example.com" overrides one for "example.com".
     */
    fun ruleFor(host: String): SiteRule? {
        val h = host.lowercase()
        return sites.filter { it.matchesHost(h) }.maxByOrNull { it.domain.length }
    }

    companion object {

        fun fromJson(json: JSONObject): SiteRulesIndex {
            val sites = mutableListOf<SiteRule>()
            val arr = json.optJSONArray("sites") ?: JSONArray()
            for (i in 0 until arr.length()) {
                val obj = arr.optJSONObject(i) ?: continue
                SiteRule.fromJson(obj)?.let { sites.add(it) }
            }
            return SiteRulesIndex(json.optInt("version", 1), sites)
        }
    }
}
